    answer TEXT,
    grounded CHAR(1),
    status_id VARCHAR(63) NOT NULL,
    error_text VARCHAR(4000),
    input_tokens BIGINT,
    output_tokens BIGINT,
    cache_read_tokens BIGINT,
    cache_write_tokens BIGINT,
    cost_micros BIGINT,
    started_at TIMESTAMP(3) NOT NULL,
    ended_at TIMESTAMP(3),
    last_updated_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    last_updated_tx_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_tx_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ai_agent_run PRIMARY KEY (ai_run_id)
);
CREATE INDEX ix_ai_agent_run_1 ON ai_agent_run (agent_name, started_at);

-- How an AI action type is approved: always ask, apply automatically, or apply under a limit.
CREATE TABLE ai_action_policy (
    action_type VARCHAR(63) NOT NULL,
